package org.apache.parquet.format.converter;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.apache.parquet.format.ColumnChunk;
import org.apache.parquet.format.ColumnMetaData;
import org.apache.parquet.format.CompressionCodec;
import org.apache.parquet.format.Encoding;
import org.apache.parquet.format.FieldRepetitionType;
import org.apache.parquet.format.RowGroup;
import org.apache.parquet.format.SchemaElement;
import org.apache.parquet.format.Type;
import org.apache.parquet.io.ParquetDecodingException;
import org.apache.parquet.schema.MessageType;
import org.apache.parquet.schema.MessageTypeParser;
import org.apache.parquet.format.FileMetaData;
import org.apache.parquet.hadoop.metadata.BlockMetaData;
import org.apache.parquet.hadoop.metadata.ParquetMetadata;

public class ParquetMetadataConverterFromParquetMetadataTests {

  @Test
  public void convertsRowGroupAndColumnMetadata() throws Exception {
    org.apache.parquet.format.FileMetaData input = createFileMetadata(
        "message schema { required int32 id; }",
        Collections.singletonList(createColumnChunk("id", "file.parquet", 100L)));

    RowGroup rowGroup = input.getRow_groups().get(0);
    Map<RowGroup, Long> rowIndexOffsets = new HashMap<>();
    rowIndexOffsets.put(rowGroup, 37L);

    org.apache.parquet.hadoop.metadata.ParquetMetadata result =
        new ParquetMetadataConverter().fromParquetMetadata(
            input, null, false, rowIndexOffsets);

    org.apache.parquet.hadoop.metadata.BlockMetaData block = result.getBlocks().get(0);

    assertEquals(1, result.getBlocks().size());
    assertEquals(12L, block.getRowCount());
    assertEquals(256L, block.getTotalByteSize());
    assertEquals(37L, block.getRowIndexOffset());
    assertEquals(4, block.getOrdinal());
    assertEquals("file.parquet", block.getPath());
    assertEquals(1, block.getColumns().size());
    assertEquals("id", block.getColumns().get(0).getPath().toDotString());
    assertEquals(100L, block.getColumns().get(0).getStartingPos());
  }

  @Test
  public void preservesLegacyRowGroupWithoutOrdinalOrRowIndexOffset() throws Exception {
    org.apache.parquet.format.FileMetaData input = createFileMetadata(
        "message schema { required int32 id; }",
        Collections.singletonList(createColumnChunk("id", null, 11L)));

    RowGroup rowGroup = input.getRow_groups().get(0);
    rowGroup.unsetOrdinal();

    org.apache.parquet.hadoop.metadata.ParquetMetadata result =
        new ParquetMetadataConverter().fromParquetMetadata(
            input, null, false, Collections.emptyMap());

    org.apache.parquet.hadoop.metadata.BlockMetaData block = result.getBlocks().get(0);

    assertEquals(1, result.getBlocks().size());
    assertEquals(12L, block.getRowCount());
    assertEquals(256L, block.getTotalByteSize());
    assertNull(block.getRowIndexOffset());
    assertNull(block.getOrdinal());
    assertNull(block.getPath());
    assertEquals(11L, block.getColumns().get(0).getStartingPos());
  }

  @Test
  public void rejectsColumnChunksStoredInDifferentFiles() throws Exception {
    org.apache.parquet.format.FileMetaData input = createFileMetadata(
        "message schema { required int32 id; required int32 value; }",
        Arrays.asList(
            createColumnChunk("id", "first.parquet", 10L),
            createColumnChunk("value", "second.parquet", 20L)));

    ParquetDecodingException exception = assertThrows(
        ParquetDecodingException.class,
        () -> new ParquetMetadataConverter().fromParquetMetadata(
            input, null, false, Collections.emptyMap()));

    assertEquals(
        "all column chunks of the same row group must be in the same file for now",
        exception.getMessage());
  }

  @Test
  public void rejectsNullParquetMetadata() {
    assertThrows(
        NullPointerException.class,
        () -> new ParquetMetadataConverter().fromParquetMetadata(
            null, null, false, Collections.emptyMap()));
  }

  private static org.apache.parquet.format.FileMetaData createFileMetadata(
      String schemaText,
      List<ColumnChunk> columns) {
    MessageType messageType = MessageTypeParser.parseMessageType(schemaText);
    List<SchemaElement> schema = new ArrayList<>();

    SchemaElement root = new SchemaElement("schema");
    root.setNum_children(messageType.getFieldCount());
    schema.add(root);

    for (org.apache.parquet.schema.Type field : messageType.getFields()) {
      SchemaElement element = new SchemaElement(field.getName());
      element.setType(Type.INT32);
      element.setRepetition_type(FieldRepetitionType.REQUIRED);
      schema.add(element);
    }

    RowGroup rowGroup = new RowGroup();
    rowGroup.setColumns(columns);
    rowGroup.setNum_rows(12L);
    rowGroup.setTotal_byte_size(256L);
    rowGroup.setOrdinal((short) 4);

    org.apache.parquet.format.FileMetaData metadata =
        new org.apache.parquet.format.FileMetaData();
    metadata.setVersion(1);
    metadata.setSchema(schema);
    metadata.setNum_rows(12L);
    metadata.setRow_groups(Collections.singletonList(rowGroup));
    metadata.setCreated_by("parquet-mr version 1.12.0");
    metadata.setKey_value_metadata(Collections.emptyList());
    return metadata;
  }

  private static ColumnChunk createColumnChunk(
      String path, String filePath, long dataPageOffset) {
    ColumnMetaData metadata = new ColumnMetaData(
        Type.INT32,
        Collections.singletonList(Encoding.PLAIN),
        Collections.singletonList(path),
        CompressionCodec.UNCOMPRESSED,
        12L,
        128L,
        128L,
        dataPageOffset);

    ColumnChunk columnChunk = new ColumnChunk();
    columnChunk.setFile_path(filePath);
    columnChunk.setMeta_data(metadata);
    return columnChunk;
  }
}
